    NodeEnvironment nodeEnvironment;
    @Mock
    NamedWriteableRegistry namedWriteableRegistry;
    @Mock
    IndexNameExpressionResolver indexNameExpressionResolver;
    @Mock
    Supplier<RepositoriesService> repositoriesServiceSupplier;

    Settings settings;
