    @Test
    public void test_getRestHandlers_successful() {
        List<RestHandler> restHandlers = toolPlugin
            .getRestHandlers(
                settings,
                restController,
                clusterSettings,
                indexScopedSettings,
                settingsFilter,
                indexNameExpressionResolver,
                nodesInCluster
