        assertEquals("doc2", docs.get(0).getAsJsonObject().get("_id").getAsString());
        assertEquals("doc3", docs.get(1).getAsJsonObject().get("_id").getAsString());
        assertEquals("doc4", docs.get(2).getAsJsonObject().get("_id").getAsString());
