    @SneakyThrows
    protected void updateClusterSettings(String settingKey, Object value) {
        XContentBuilder builder = XContentFactory
            .jsonBuilder()
            .startObject()
            .startObject("persistent")
            .field(settingKey, value)
            .endObject()
            .endObject();
        Response response = makeRequest(
            client(),
            "PUT",
            "_cluster/settings",
            null,
            builder.toString(),
            ImmutableList.of(new BasicHeader(HttpHeaders.USER_AGENT, ""))
        );

        assertEquals(RestStatus.OK, RestStatus.fromCode(response.getStatusLine().getStatusCode()));
    }

    @SneakyThrows
    private Map<String, Object> parseResponseToMap(Response response) {
        String responseBody = EntityUtils.toString(response.getEntity());
        try {
            return XContentHelper.convertToMap(XContentType.JSON.xContent(), responseBody, false);
        } catch (Exception e) {
            logger.error("failed to parse response to map: {}", responseBody, e);
            return Collections.emptyMap();
        }
    }

    @SneakyThrows
    private Object parseFieldFromResponse(Response response, String field) {
        assertNotNull(field);
        Map map = parseResponseToMap(response);
        Object result = map.get(field);
        assertNotNull(result);
        return result;
    }

    protected String createConnector(String requestBody) {
